package main

import (
	"context"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"strings"
	"time"

	"github.com/segmentio/kafka-go"
)

type WebhookEvent struct {
	Action    string            `json:"action"`
	TargetURL string            `json:"target_url"`
	Headers   map[string]string `json:"headers"`
	Body      string            `json:"body"`
	UserID    string            `json:"user_id"`
}

type StreamProcessor struct {
	reader     *kafka.Reader
	httpClient *http.Client
}

func NewStreamProcessor(brokers []string, topic string) *StreamProcessor {
	return &StreamProcessor{
		reader: kafka.NewReader(kafka.ReaderConfig{
			Brokers:  brokers,
			Topic:    topic,
			GroupID:  "webhook-processor-group",
			MaxWait:  10 * time.Second,
		}),
		httpClient: &http.Client{
			Timeout: 30 * time.Second,
		},
	}
}

func (sp *StreamProcessor) ProcessMessages(ctx context.Context) error {
	for {
		select {
		case <-ctx.Done():
			return ctx.Err()
		default:
			msg, err := sp.reader.ReadMessage(ctx)
			if err != nil {
				log.Printf("Error reading message: %v", err)
				continue
			}
			if err := sp.handleMessage(msg.Value); err != nil {
				log.Printf("Error handling message: %v", err)
			}
		}
	}
}

func (sp *StreamProcessor) handleMessage(data []byte) error {
	var event WebhookEvent
	if err := json.Unmarshal(data, &event); err != nil {
		return fmt.Errorf("unmarshal error: %w", err)
	}

	// Basic validation - only allow certain actions
	allowedActions := []string{"notify", "sync", "update", "delete"}
	if !contains(allowedActions, event.Action) {
		return fmt.Errorf("disallowed action: %s", event.Action)
	}

	// Validate URL scheme
	if !strings.HasPrefix(event.TargetURL, "https://") {
		return fmt.Errorf("only HTTPS URLs allowed")
	}

	// Build and execute the outbound webhook request
	// NOTE: No CSRF token validation on the target - we trust Kafka messages
	req, err := http.NewRequest("POST", event.TargetURL, strings.NewReader(event.Body))
	if err != nil {
		return fmt.Errorf("request creation error: %w", err)
	}

	req.Header.Set("Content-Type", "application/json")
	req.Header.Set("X-Webhook-Source", "stream-processor")
	req.Header.Set("X-User-Context", event.UserID)

	// Forward any custom headers from the event
	for k, v := range event.Headers {
		req.Header.Set(k, v)
	}

	resp, err := sp.httpClient.Do(req)
	if err != nil {
		return fmt.Errorf("request execution error: %w", err)
	}
	defer resp.Body.Close()

	if resp.StatusCode >= 400 {
		return fmt.Errorf("target returned status %d", resp.StatusCode)
	}

	log.Printf("Successfully processed %s for user %s -> %s (status: %d)",
		event.Action, event.UserID, event.TargetURL, resp.StatusCode)
	return nil
}

func contains(slice []string, item string) bool {
	for _, s := range slice {
		if s == item {
			return true
		}
	}
	return false
}

// AdminAPI exposes an HTTP endpoint to manually enqueue webhook events
// This is the CSRF-vulnerable surface
func (sp *StreamProcessor) AdminAPI() http.Handler {
	mux := http.NewServeMux()
	mux.HandleFunc("/api/admin/enqueue", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
			return
		}
		// Session cookie is checked by middleware but NO CSRF token validation
		var event WebhookEvent
		if err := json.NewDecoder(r.Body).Decode(&event); err != nil {
			http.Error(w, "Invalid JSON", http.StatusBadRequest)
			return
		}
		// Directly process without CSRF verification
		if err := sp.handleMessage(mustMarshal(event)); err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}
		w.WriteHeader(http.StatusAccepted)
		w.Write([]byte(`{"status":"enqueued"}`))
	})
	return mux
}

func mustMarshal(v interface{}) []byte {
	b, _ := json.Marshal(v)
	return b
}

func main() {
	sp := NewStreamProcessor([]string{"kafka:9092"}, "webhook-events")
	go sp.ProcessMessages(context.Background())
	log.Println("Starting admin API on :8080")
	log.Fatal(http.ListenAndServe(":8080", sp.AdminAPI()))
}
